BEGIN;
CREATE TABLE credential_class_gates (
 credential_class text PRIMARY KEY REFERENCES custody_inventory_models(credential_class),
 gate_id text NOT NULL, passed boolean NOT NULL DEFAULT false,
 threat_revision integer NOT NULL, threat_digest text NOT NULL CHECK (threat_digest ~ '^[0-9a-f]{64}$'),
 UNIQUE (credential_class,gate_id)
);
INSERT INTO credential_class_gates VALUES ('3.3','C3',true,8,'629ae3f2654aba46e4c1158fc234c6b24831a369505ccf41878af3207b091089');
REVOKE ALL ON credential_class_gates FROM PUBLIC,engram_app,engram_maintenance;
GRANT SELECT ON credential_class_gates TO engram_migrator;
ALTER TABLE credential_class_gates ENABLE ROW LEVEL SECURITY; ALTER TABLE credential_class_gates FORCE ROW LEVEL SECURITY;
CREATE POLICY credential_class_gates_migrator_read ON credential_class_gates FOR SELECT TO PUBLIC USING (current_user = 'engram_migrator');
CREATE POLICY credential_class_gates_migrator_write ON credential_class_gates FOR ALL TO PUBLIC USING (current_user = 'engram_migrator') WITH CHECK (current_user = 'engram_migrator');
CREATE OR REPLACE FUNCTION mint_custody_reference(p_credential_class text,p_namespace epr_namespace,p_model custody_model,p_key_locator text,p_metadata jsonb DEFAULT '{}') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE principal uuid:=nullif(current_setting('app.principal_id',true),'')::uuid;t uuid;p uuid;g founder_authorities%ROWTYPE;canonical custody_model;gate credential_class_gates%ROWTYPE;row_id uuid:=gen_random_uuid();ref text;ms bigint;hexms text;required text; BEGIN IF principal IS NULL THEN RAISE EXCEPTION 'MINT_AUTHORITY_REFUSED' USING ERRCODE='42501';END IF;SELECT * INTO g FROM founder_authorities WHERE principal_id=principal FOR SHARE;IF NOT FOUND OR g.revoked_at IS NOT NULL OR g.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'MINT_AUTHORITY_REFUSED' USING ERRCODE='42501';END IF;SELECT custody_model INTO canonical FROM custody_inventory_models WHERE credential_class=p_credential_class;IF canonical IS NULL OR p_model<>canonical THEN RAISE EXCEPTION 'MODEL_DERIVATION_REFUSED' USING ERRCODE='42501';END IF;SELECT * INTO gate FROM credential_class_gates WHERE credential_class=p_credential_class FOR SHARE;IF NOT FOUND OR NOT gate.passed OR gate.threat_revision<>8 OR gate.threat_digest<>'629ae3f2654aba46e4c1158fc234c6b24831a369505ccf41878af3207b091089' THEN RAISE EXCEPTION 'CLASS_GATE_NOT_PASSED' USING ERRCODE='42501';END IF;SELECT d.tenant_id,d.project_id INTO t,p FROM derive_mint_membership(principal) d;IF t IS NULL THEN RAISE EXCEPTION 'TENANT_PROJECT_REFUSED' USING ERRCODE='42501';END IF;PERFORM set_config('app.tenant_id',t::text,true);IF p_namespace IN ('shape','installation') THEN RAISE EXCEPTION 'NAMESPACE_REFUSED' USING ERRCODE='42501';END IF;required:=format('custody:mint:%s:%s:%s',p_namespace,p_credential_class,p_model);IF NOT(required=ANY(g.scopes)) THEN RAISE EXCEPTION 'SCOPE_EXCEEDED' USING ERRCODE='42501';END IF;IF p_model='B' AND p_key_locator IS NULL THEN RAISE EXCEPTION 'KEY_LOCATOR_REQUIRED';END IF;IF p_model='A' AND p_key_locator IS NOT NULL THEN RAISE EXCEPTION 'KEY_LOCATOR_FORBIDDEN';END IF;IF NOT custody_metadata_keys_allowed(p_metadata) THEN RAISE EXCEPTION 'METADATA_KEY_REFUSED';END IF;ms:=floor(extract(epoch from clock_timestamp())*1000)::bigint;hexms:=lpad(to_hex(ms),12,'0');ref:=format('epr:%s:%s-%s-7%s-8%s-%s',p_namespace,substr(hexms,1,8),substr(hexms,9,4),substr(replace(row_id::text,'-',''),1,3),substr(replace(row_id::text,'-',''),18,3),substr(replace(row_id::text,'-',''),21,12));INSERT INTO custody_rows(id,tenant_id,project_id,namespace,credential_class,custody_model,inventory_model,required_scope,key_locator,metadata,minted_by_principal_id,retention_policy) VALUES(row_id,t,p,p_namespace,p_credential_class,p_model,canonical::text,required,p_key_locator,p_metadata,principal,'RET-AUDIT-400');INSERT INTO minted_references VALUES(ref,row_id,t,p,p_namespace,clock_timestamp());INSERT INTO custody_audit(tenant_id,project_id,namespace,credential_class,action,outcome,principal_id,reference) VALUES(t,p,p_namespace,p_credential_class,'mint','success',principal,ref);RETURN ref;END $$;
REVOKE ALL ON FUNCTION mint_custody_reference(text,epr_namespace,custody_model,text,jsonb) FROM PUBLIC,engram_app; GRANT EXECUTE ON FUNCTION mint_custody_reference(text,epr_namespace,custody_model,text,jsonb) TO engram_maintenance;
COMMIT;
